fn solve(a: i8, b: i8, c: i8) -> i8 {
    // We'll try all possible target values from max(a,b,c) up to max+4
    // Because increasing beyond max+4 won't reduce operations (since increments are +2 or +1+1),
    // and due to small input ranges, brute forcing target is efficient.

    let max_val = *[a, b, c].iter().max().unwrap();

    let mut best_ops = i8::MAX;

    // Check possible targets from max_val up to max_val+4
    // This covers all plausible targets considering the operations
    for target in max_val..=max_val + 4 {
        let diffs = [
            target - a,
            target - b,
            target - c,
        ];

        // Count how many are odd diffs
        let odds = diffs.iter().filter(|&&d| d % 2 != 0).count() as i8;

        // Sum of diffs
        let sum: i8 = diffs.iter().sum();

        // The parity and sum relationship:
        // - each operation increases total by 2
        // - actions:
        //   * +2 to one integer (increases sum by 2, affects parity of that integer)
        //   * +1 to two different integers (increases sum by 2, flips parity of both)

        // Number of operations must be sum/2 since each op adds 2 increments in total
        // However, we must ensure that the parity matches:
        // The number of operations >= max(odds, sum/2)
        // Why? Because increments by +1 change odds count by 2 (always even number of odds changed),
        // so the number of operations must be enough to fix the parity discrepancies.

        let ops = std::cmp::max(odds, sum / 2);
        if ops < best_ops {
            best_ops = ops;
        }
    }

    best_ops
}